import useControlled from "./../utils/useControlled";
import { mergeProps } from "solid-js";
export default function usePagination(inProps = {}) {
    // keep default values in sync with @default tags in Pagination.propTypes
    const props = mergeProps({
        boundaryCount: 1,
        componentName: "usePagination",
        count: 1,
        defaultPage: 1,
        disabled: false,
        hideNextButton: false,
        hidePrevButton: false,
        showFirstButton: false,
        showLastButton: false,
        siblingCount: 1,
    }, inProps);
    const [page, setPageState] = useControlled({
        controlled: () => props.page,
        default: () => props.defaultPage,
        name: props.componentName,
        state: "page",
    });
    const handleClick = (event, value) => {
        if (!props.page) {
            setPageState(value);
        }
        if (props.onChange) {
            props.onChange(event, value);
        }
    };
    // https://dev.to/namirsab/comment/2050
    const range = (start, end) => {
        const length = end - start + 1;
        return Array.from({ length }, (_, i) => start + i);
    };
    const startPages = () => range(1, Math.min(props.boundaryCount, props.count));
    const endPages = () => range(Math.max(props.count - props.boundaryCount + 1, props.boundaryCount + 1), props.count);
    const siblingsStart = () => Math.max(Math.min(
    // Natural start
    page() - props.siblingCount, 
    // Lower boundary when page is high
    props.count - props.boundaryCount - props.siblingCount * 2 - 1), 
    // Greater than startPages
    props.boundaryCount + 2);
    const siblingsEnd = () => Math.min(Math.max(
    // Natural end
    page() + props.siblingCount, 
    // Upper boundary when page is low
    props.boundaryCount + props.siblingCount * 2 + 2), 
    // Less than endPages
    endPages().length > 0 ? endPages()[0] - 2 : props.count - 1);
    // Basic list of items to render
    // e.g. itemList = ['first', 'previous', 1, 'ellipsis', 4, 5, 6, 'ellipsis', 10, 'next', 'last']
    const itemList = () => [
        ...(props.showFirstButton ? ["first"] : []),
        ...(props.hidePrevButton ? [] : ["previous"]),
        ...startPages(),
        // Start ellipsis
        ...(siblingsStart() > props.boundaryCount + 2
            ? ["start-ellipsis"]
            : props.boundaryCount + 1 < props.count - props.boundaryCount
                ? [props.boundaryCount + 1]
                : []),
        // Sibling pages
        ...range(siblingsStart(), siblingsEnd()),
        // End ellipsis
        ...(siblingsEnd() < props.count - props.boundaryCount - 1
            ? ["end-ellipsis"]
            : props.count - props.boundaryCount > props.boundaryCount
                ? [props.count - props.boundaryCount]
                : []),
        ...endPages(),
        ...(props.hideNextButton ? [] : ["next"]),
        ...(props.showLastButton ? ["last"] : []),
    ];
    // Map the button type to its page number
    const buttonPage = (type) => {
        switch (type) {
            case "first":
                return 1;
            case "previous":
                return page() - 1;
            case "next":
                return page() + 1;
            case "last":
                return props.count;
            default:
                return null;
        }
    };
    // Convert the basic item list to PaginationItem props objects
    const items = () => itemList().map((item) => {
        return typeof item === "number"
            ? {
                onClick: (event) => {
                    handleClick(event, item);
                },
                type: "page",
                page: item,
                selected: item === page(),
                disabled: props.disabled,
                "aria-current": item === page() ? "true" : undefined,
            }
            : {
                onClick: (event) => {
                    handleClick(event, buttonPage(item));
                },
                type: item,
                page: buttonPage(item),
                selected: false,
                disabled: props.disabled ||
                    (item.indexOf("ellipsis") === -1 &&
                        (item === "next" || item === "last"
                            ? page() >= props.count
                            : page() <= 1)),
            };
    });
    return {
        get items() {
            return items();
        },
    };
}
